# Let me carefully reconstruct what's happening in each case
inputs = ['cwwe', 'wh', 'exw', 'vwvu', 'xixxk']
outputs = ['czze', 'zh', 'exz', 'yzzvzgx', 'xixxy']

print("Detailed breakdown of all transformations:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\n{i}: '{inp}' -> '{out}'")

    # Find positions where they differ
    diff_positions = []
    for j, (c1, c2) in enumerate(zip(inp, out)):
        if c1 != c2:
            diff_positions.append((j, c1, c2))

    # For cases where lengths differ
    if len(inp) != len(out):
        # Check if it's just insertion/deletion
        shorter = min(len(inp), len(out))
        for j in range(shorter):
            if inp[j] != out[j]:
                diff_positions.append((j, inp[j], out[j]))

        # Add any extra characters at the end
        if len(out) > len(inp):
            for j in range(len(inp), len(out)):
                diff_positions.append((j, '-', out[j]))
        elif len(inp) > len(out):
            for j in range(len(out), len(inp)):
                diff_positions.append((j, inp[j], '-'))

    print(f"  Differences: {diff_positions}")

    # Special case for length change
    if len(inp) != len(out):
        print(f"  Length change: {len(inp)} -> {len(out)}")

